//! The Kani harness: the specification's register rules over an image this
//! harness owns. Every number below is computed by the generator from the
//! solved topology and the register source, not read from `lib.rs`.
//!
//! @generated by `aethelgard-svd-hal` (AET-WO-1400). Do not edit: the regeneration
//! test compares every byte of this tree with the generator's output.
//!
//! - Solved topology of specification sha256 `acd60081f2d111b1b1ed0d974078fff45ccf2a967ec5f42317417f8ce68149d1`.
//! - Register facts: `https://github.com/STMicroelectronics/cmsis-device-h7` at `8f922cdc7cc6de2344e75ddd657889f4ff761790`, `stm32h753xx.h` sha256 `4f6def439a9fa94705303fe227d34308048c44bd36263d311aa54cc94f8398f5`.
//! - Pin data: `STM32_open_pin_data` at `7d1f1514ed5583ec5007ad91236b4e1d377295b1`.

use crate::board::sealed;
use crate::*;

/// The harness-owned register image, and the oracle for the ordering rules.
#[derive(Clone, Copy)]
struct Image {
    rcc: [u32; 76],
    gpioa: [u32; 10],
    gpiob: [u32; 10],
    i2c1: [u32; 11],
    spi1: [u32; 21],
}

impl Image {
    fn slot(&mut self, block: Block, offset: usize) -> &mut u32 {
        let words: &mut [u32] = match block {
            Block::Rcc => &mut self.rcc,
            Block::GpioA => &mut self.gpioa,
            Block::GpioB => &mut self.gpiob,
            Block::I2c1 => &mut self.i2c1,
            Block::Spi1 => &mut self.spi1,
        };
        kani::assert(
            offset % 4 == 0 && offset / 4 < words.len(),
            "register access past the end of its block",
        );
        &mut words[offset / 4]
    }

    /// A gated block may not be read or written.
    fn clocked(&self, block: Block) {
        match block {
            Block::Rcc => {}
            Block::GpioA => kani::assert(
                self.rcc[56] & 0x00000001 != 0,
                "GpioA accessed before RCC_AHB4ENR bit 0 is set",
            ),
            Block::GpioB => kani::assert(
                self.rcc[56] & 0x00000002 != 0,
                "GpioB accessed before RCC_AHB4ENR bit 1 is set",
            ),
            Block::I2c1 => kani::assert(
                self.rcc[58] & 0x00200000 != 0,
                "I2c1 accessed before RCC_APB1LENR bit 21 is set",
            ),
            Block::Spi1 => kani::assert(
                self.rcc[60] & 0x00001000 != 0,
                "Spi1 accessed before RCC_APB2ENR bit 12 is set",
            ),
        }
    }
}

impl sealed::Sealed for Image {}

impl Registers for Image {
    fn read(&mut self, _: sealed::Token, block: Block, offset: usize) -> u32 {
        self.clocked(block);
        *self.slot(block, offset)
    }
    fn write(&mut self, _: sealed::Token, block: Block, offset: usize, value: u32) {
        self.clocked(block);
        if block == Block::I2c1 && offset == 0x10 {
            kani::assert(
                self.i2c1[0] & 0x00000001 == 0,
                "I2c1 TIMINGR written while the peripheral is enabled",
            );
        }
        if block == Block::Spi1 && offset == 0x0c {
            kani::assert(
                self.spi1[0] & 0x00000001 == 0,
                "Spi1 CFG2 written while the peripheral is enabled",
            );
        }
        if block == Block::GpioA && offset == 0x18 {
            kani::assert(value == 0x00000001 || value == 0x00010000, "GpioA BSRR write touches a pin no solved output owns");
        }
        if block == Block::GpioA && offset == 0x00 {
            let old = self.gpioa[0];
            if value & 0x00000003 != old & 0x00000003 {
                kani::assert(value & 0x00000003 == 0x00000001, "PA0's mode moved to one its role never takes");
                kani::assert(
                    self.gpioa[1] & 0x00000001 == 0x00000000
                        && self.gpioa[2] & 0x00000003 == 0x00000000
                        && self.gpioa[3] & 0x00000003 == 0x00000000
                        && self.gpioa[6] == 0x00000001,
                    "PA0 entered its mode before its other fields were final",
                );
            }
            if value & 0x00000c00 != old & 0x00000c00 {
                kani::assert(value & 0x00000c00 == 0x00000800, "PA5's mode moved to one its role never takes");
                kani::assert(
                    self.gpioa[1] & 0x00000020 == 0x00000000
                        && self.gpioa[2] & 0x00000c00 == 0x00000800
                        && self.gpioa[3] & 0x00000c00 == 0x00000000
                        && self.gpioa[8] & 0x00f00000 == 0x00500000,
                    "PA5 entered its mode before its other fields were final",
                );
            }
            if value & 0x00003000 != old & 0x00003000 {
                kani::assert(value & 0x00003000 == 0x00002000, "PA6's mode moved to one its role never takes");
                kani::assert(
                    self.gpioa[1] & 0x00000040 == 0x00000000
                        && self.gpioa[2] & 0x00003000 == 0x00002000
                        && self.gpioa[3] & 0x00003000 == 0x00000000
                        && self.gpioa[8] & 0x0f000000 == 0x05000000,
                    "PA6 entered its mode before its other fields were final",
                );
            }
            if value & 0x0000c000 != old & 0x0000c000 {
                kani::assert(value & 0x0000c000 == 0x00008000, "PA7's mode moved to one its role never takes");
                kani::assert(
                    self.gpioa[1] & 0x00000080 == 0x00000000
                        && self.gpioa[2] & 0x0000c000 == 0x00008000
                        && self.gpioa[3] & 0x0000c000 == 0x00000000
                        && self.gpioa[8] & 0xf0000000 == 0x50000000,
                    "PA7 entered its mode before its other fields were final",
                );
            }
            kani::assert(
                value & !0x0000fc03 == old & !0x0000fc03,
                "a GpioA MODER write moved a pin the topology does not use",
            );
        }
        if block == Block::GpioB && offset == 0x18 {
            kani::assert(false, "GpioB BSRR write touches a pin no solved output owns");
        }
        if block == Block::GpioB && offset == 0x00 {
            let old = self.gpiob[0];
            if value & 0x00003000 != old & 0x00003000 {
                kani::assert(value & 0x00003000 == 0x00002000, "PB6's mode moved to one its role never takes");
                kani::assert(
                    self.gpiob[1] & 0x00000040 == 0x00000040
                        && self.gpiob[2] & 0x00003000 == 0x00000000
                        && self.gpiob[3] & 0x00003000 == 0x00000000
                        && self.gpiob[8] & 0x0f000000 == 0x04000000,
                    "PB6 entered its mode before its other fields were final",
                );
            }
            if value & 0x0000c000 != old & 0x0000c000 {
                kani::assert(value & 0x0000c000 == 0x00008000, "PB7's mode moved to one its role never takes");
                kani::assert(
                    self.gpiob[1] & 0x00000080 == 0x00000080
                        && self.gpiob[2] & 0x0000c000 == 0x00000000
                        && self.gpiob[3] & 0x0000c000 == 0x00000000
                        && self.gpiob[8] & 0xf0000000 == 0x40000000,
                    "PB7 entered its mode before its other fields were final",
                );
            }
            kani::assert(
                value & !0x0000f000 == old & !0x0000f000,
                "a GpioB MODER write moved a pin the topology does not use",
            );
        }
        *self.slot(block, offset) = value;
    }
}

/// The state the specification allows, from any starting image.
fn check_final(before: &Image, after: &Image, i2c1_timingr: u32) {
    kani::assert(
        after.gpioa[0] & 0x0000fc03 == 0x0000a801,
        "GpioA word 0: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpioa[0] & !0x0000fc03 == before.gpioa[0] & !0x0000fc03,
        "GpioA word 0: an unsolved pin's field changed",
    );
    kani::assert(
        after.gpioa[1] & 0x000000e1 == 0x00000000,
        "GpioA word 1: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpioa[1] & !0x000000e1 == before.gpioa[1] & !0x000000e1,
        "GpioA word 1: an unsolved pin's field changed",
    );
    kani::assert(
        after.gpioa[2] & 0x0000fc03 == 0x0000a800,
        "GpioA word 2: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpioa[2] & !0x0000fc03 == before.gpioa[2] & !0x0000fc03,
        "GpioA word 2: an unsolved pin's field changed",
    );
    kani::assert(
        after.gpioa[3] & 0x0000fc03 == 0x00000000,
        "GpioA word 3: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpioa[3] & !0x0000fc03 == before.gpioa[3] & !0x0000fc03,
        "GpioA word 3: an unsolved pin's field changed",
    );
    kani::assert(
        after.gpioa[8] & 0xfff00000 == 0x55500000,
        "GpioA word 8: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpioa[8] & !0xfff00000 == before.gpioa[8] & !0xfff00000,
        "GpioA word 8: an unsolved pin's field changed",
    );
    kani::assert(after.gpioa[4] == before.gpioa[4], "GpioA word 4 changed");
    kani::assert(after.gpioa[5] == before.gpioa[5], "GpioA word 5 changed");
    kani::assert(after.gpioa[7] == before.gpioa[7], "GpioA word 7 changed");
    kani::assert(after.gpioa[9] == before.gpioa[9], "GpioA word 9 changed");
    kani::assert(
        after.gpiob[0] & 0x0000f000 == 0x0000a000,
        "GpioB word 0: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpiob[0] & !0x0000f000 == before.gpiob[0] & !0x0000f000,
        "GpioB word 0: an unsolved pin's field changed",
    );
    kani::assert(
        after.gpiob[1] & 0x000000c0 == 0x000000c0,
        "GpioB word 1: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpiob[1] & !0x000000c0 == before.gpiob[1] & !0x000000c0,
        "GpioB word 1: an unsolved pin's field changed",
    );
    kani::assert(
        after.gpiob[2] & 0x0000f000 == 0x00000000,
        "GpioB word 2: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpiob[2] & !0x0000f000 == before.gpiob[2] & !0x0000f000,
        "GpioB word 2: an unsolved pin's field changed",
    );
    kani::assert(
        after.gpiob[3] & 0x0000f000 == 0x00000000,
        "GpioB word 3: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpiob[3] & !0x0000f000 == before.gpiob[3] & !0x0000f000,
        "GpioB word 3: an unsolved pin's field changed",
    );
    kani::assert(
        after.gpiob[8] & 0xff000000 == 0x44000000,
        "GpioB word 8: a solved pin's field is not what the specification fixes",
    );
    kani::assert(
        after.gpiob[8] & !0xff000000 == before.gpiob[8] & !0xff000000,
        "GpioB word 8: an unsolved pin's field changed",
    );
    kani::assert(after.gpiob[4] == before.gpiob[4], "GpioB word 4 changed");
    kani::assert(after.gpiob[5] == before.gpiob[5], "GpioB word 5 changed");
    kani::assert(after.gpiob[6] == before.gpiob[6], "GpioB word 6 changed");
    kani::assert(after.gpiob[7] == before.gpiob[7], "GpioB word 7 changed");
    kani::assert(after.gpiob[9] == before.gpiob[9], "GpioB word 9 changed");
    let mut rcc = before.rcc;
    rcc[56] |= 0x00000003;
    rcc[58] |= 0x00200000;
    rcc[60] |= 0x00001000;
    // Word by word: `==` on the arrays is a `memcmp` loop under CBMC.
    for i in 0..76 {
        kani::assert(after.rcc[i] == rcc[i], "RCC is not before plus exactly the solved clock gates");
    }
    kani::assert(after.i2c1[0] & 0x00000001 != 0, "I2c1 is not enabled");
    kani::assert(
        after.i2c1[0] & !0x00000001 == before.i2c1[0] & !0x00000001,
        "I2c1 CR1 changed beyond its enable bit",
    );
    kani::assert(
        after.i2c1[4] == i2c1_timingr,
        "I2c1 TIMINGR is not the chosen speed's",
    );
    kani::assert(after.i2c1[1] == before.i2c1[1], "I2c1 word 1 changed");
    kani::assert(after.i2c1[2] == before.i2c1[2], "I2c1 word 2 changed");
    kani::assert(after.i2c1[3] == before.i2c1[3], "I2c1 word 3 changed");
    kani::assert(after.i2c1[5] == before.i2c1[5], "I2c1 word 5 changed");
    kani::assert(after.i2c1[6] == before.i2c1[6], "I2c1 word 6 changed");
    kani::assert(after.i2c1[7] == before.i2c1[7], "I2c1 word 7 changed");
    kani::assert(after.i2c1[8] == before.i2c1[8], "I2c1 word 8 changed");
    kani::assert(after.i2c1[9] == before.i2c1[9], "I2c1 word 9 changed");
    kani::assert(after.spi1[0] & 0x00000001 != 0, "Spi1 is not enabled");
    kani::assert(
        after.spi1[0] & !0x00000001 == before.spi1[0] & !0x00000001,
        "Spi1 CR1 changed beyond its enable bit",
    );
    kani::assert(after.spi1[3] & 0x00400000 != 0, "Spi1 is not a master");
    kani::assert(
        after.spi1[3] & !0x00400000 == before.spi1[3] & !0x00400000,
        "Spi1 CFG2 changed beyond MASTER",
    );
    kani::assert(after.spi1[1] == before.spi1[1], "Spi1 word 1 changed");
    kani::assert(after.spi1[2] == before.spi1[2], "Spi1 word 2 changed");
    kani::assert(after.spi1[4] == before.spi1[4], "Spi1 word 4 changed");
    kani::assert(after.spi1[5] == before.spi1[5], "Spi1 word 5 changed");
    kani::assert(after.spi1[6] == before.spi1[6], "Spi1 word 6 changed");
    kani::assert(after.spi1[7] == before.spi1[7], "Spi1 word 7 changed");
    kani::assert(after.spi1[9] == before.spi1[9], "Spi1 word 9 changed");
    kani::assert(after.spi1[10] == before.spi1[10], "Spi1 word 10 changed");
    kani::assert(after.spi1[11] == before.spi1[11], "Spi1 word 11 changed");
    kani::assert(after.spi1[12] == before.spi1[12], "Spi1 word 12 changed");
    kani::assert(after.spi1[13] == before.spi1[13], "Spi1 word 13 changed");
    kani::assert(after.spi1[14] == before.spi1[14], "Spi1 word 14 changed");
    kani::assert(after.spi1[15] == before.spi1[15], "Spi1 word 15 changed");
    kani::assert(after.spi1[16] == before.spi1[16], "Spi1 word 16 changed");
    kani::assert(after.spi1[17] == before.spi1[17], "Spi1 word 17 changed");
    kani::assert(after.spi1[18] == before.spi1[18], "Spi1 word 18 changed");
    kani::assert(after.spi1[19] == before.spi1[19], "Spi1 word 19 changed");
    kani::assert(after.spi1[20] == before.spi1[20], "Spi1 word 20 changed");
}

/// Every order the typestate API admits: at each of 12 steps, any
/// action whose inputs exist. The `assume` admits only those orders; the
/// types forbid the rest at compile time. Each peripheral writes zero or one
/// byte when it starts, and the output pins are driven zero or one time.
#[kani::proof]
#[kani::unwind(77)]
fn every_valid_sequence() {
    let mut img = Image {
        rcc: kani::any(),
        gpioa: kani::any(),
        gpiob: kani::any(),
        i2c1: kani::any(),
        spi1: kani::any(),
    };
    let before = img;
    let board = Board::take().unwrap();
    let mut rcc = board.rcc;
    let mut gpioa = Some(board.gpioa);
    let mut gpiob = Some(board.gpiob);
    let mut i2c1 = Some(board.i2c1);
    let mut i2c1_clocked = None;
    let mut i2c1_done = false;
    let mut spi1 = Some(board.spi1);
    let mut spi1_clocked = None;
    let mut spi1_done = false;
    let mut i2c1_timingr = 0u32;
    let mut pa0 = None;
    let mut pa0_done = None;
    let mut pa5 = None;
    let mut pa5_done = None;
    let mut pa6 = None;
    let mut pa6_done = None;
    let mut pa7 = None;
    let mut pa7_done = None;
    let mut pb6 = None;
    let mut pb6_done = None;
    let mut pb7 = None;
    let mut pb7_done = None;
    for _ in 0..12 {
        let action: u8 = kani::any();
        match action {
            0 => {
                kani::assume(gpioa.is_some());
                let pins = rcc.enable_gpioa(&mut img, gpioa.take().unwrap()).split();
                pa0 = Some(pins.pa0);
                pa5 = Some(pins.pa5);
                pa6 = Some(pins.pa6);
                pa7 = Some(pins.pa7);
            }
            1 => {
                kani::assume(gpiob.is_some());
                let pins = rcc.enable_gpiob(&mut img, gpiob.take().unwrap()).split();
                pb6 = Some(pins.pb6);
                pb7 = Some(pins.pb7);
            }
            2 => {
                kani::assume(i2c1.is_some());
                i2c1_clocked = Some(rcc.enable_i2c1(&mut img, i2c1.take().unwrap()));
            }
            3 => {
                kani::assume(spi1.is_some());
                spi1_clocked = Some(rcc.enable_spi1(&mut img, spi1.take().unwrap()));
            }
            4 => {
                kani::assume(pa0.is_some());
                let mut pin = pa0.take().unwrap().into_output(&mut img);
                if kani::any() {
                    if kani::any() {
                        pin.set_low(&mut img);
                        kani::assert(img.gpioa[6] == 0x00010000, "PA0 set_low did not reset it");
                        kani::cover!(true, "PA0 driven low");
                    } else {
                        pin.set_high(&mut img);
                        kani::assert(img.gpioa[6] == 0x00000001, "PA0 set_high did not set it");
                        kani::cover!(true, "PA0 driven high");
                    }
                }
                pa0_done = Some(pin);
            }
            5 => {
                kani::assume(pa5.is_some());
                let pin = pa5.take().unwrap().into_spi1_sck(&mut img);
                pa5_done = Some(pin);
            }
            6 => {
                kani::assume(pa6.is_some());
                let pin = pa6.take().unwrap().into_spi1_miso(&mut img);
                pa6_done = Some(pin);
            }
            7 => {
                kani::assume(pa7.is_some());
                let pin = pa7.take().unwrap().into_spi1_mosi(&mut img);
                pa7_done = Some(pin);
            }
            8 => {
                kani::assume(pb6.is_some());
                let pin = pb6.take().unwrap().into_i2c1_scl(&mut img);
                pb6_done = Some(pin);
            }
            9 => {
                kani::assume(pb7.is_some());
                let pin = pb7.take().unwrap().into_i2c1_sda(&mut img);
                pb7_done = Some(pin);
            }
            10 => {
                kani::assume(i2c1_clocked.is_some() && pb6_done.is_some() && pb7_done.is_some());
                let i = i2c1_clocked.take().unwrap();
                let speed: u8 = kani::any();
                if speed == 0 {
                    i2c1_timingr = 0x10707dbc;
                    let mut bus = i.init::<i2c1_speed::Standard100k, _>(&mut img, pb6_done.take().unwrap(), pb7_done.take().unwrap());
                    kani::cover!(true, "I2C1 started at Standard100k");
                    if kani::any() {
                        let levels = [img.gpioa[6], img.gpiob[6]];
                        bus.write_byte(&mut img, kani::any());
                        kani::assert(levels == [img.gpioa[6], img.gpiob[6]], "I2C1 write_byte touched a GPIO BSRR");
                        kani::cover!(true, "I2C1 wrote a byte");
                    }
                } else {
                    i2c1_timingr = 0x00602173;
                    let mut bus = i.init::<i2c1_speed::Fast400k, _>(&mut img, pb6_done.take().unwrap(), pb7_done.take().unwrap());
                    kani::cover!(true, "I2C1 started at Fast400k");
                    if kani::any() {
                        let levels = [img.gpioa[6], img.gpiob[6]];
                        bus.write_byte(&mut img, kani::any());
                        kani::assert(levels == [img.gpioa[6], img.gpiob[6]], "I2C1 write_byte touched a GPIO BSRR");
                        kani::cover!(true, "I2C1 wrote a byte");
                    }
                }
                i2c1_done = true;
            }
            11 => {
                kani::assume(spi1_clocked.is_some() && pa5_done.is_some() && pa7_done.is_some() && pa6_done.is_some());
                let i = spi1_clocked.take().unwrap();
                let mut bus = i.init::<_>(&mut img, pa5_done.take().unwrap(), pa7_done.take().unwrap(), pa6_done.take().unwrap());
                kani::cover!(true, "SPI1 started");
                if kani::any() {
                    let levels = [img.gpioa[6], img.gpiob[6]];
                    bus.write_byte(&mut img, kani::any());
                    kani::assert(levels == [img.gpioa[6], img.gpiob[6]], "SPI1 write_byte touched a GPIO BSRR");
                    kani::cover!(true, "SPI1 wrote a byte");
                }
                spi1_done = true;
            }
            _ => kani::assume(false),
        }
    }
    kani::assert(i2c1_done, "the schedule did not start I2C1");
    kani::assert(spi1_done, "the schedule did not start SPI1");
    kani::assert(pa0_done.is_some(), "the schedule did not configure PA0");
    check_final(&before, &img, i2c1_timingr);
    kani::cover!(true, "the end of a complete schedule is reachable");
}
